const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => obj.getInfo(resolve, reject));
}

function bufferCircle(lon, lat, radiusMeters) {
  const pt = ee.Geometry.Point([lon, lat]);
  return pt.buffer(radiusMeters);
}

// Sentinel-2 SR cloud/water mask and NDVI
function prepS2ToNdvi(col) {
  return col.map(function(img) {
    const qa = img.select('QA60');
    const cloudBitMask = ee.Number(1).leftShift(10);
    const cirrusBitMask = ee.Number(1).leftShift(11);
    const cloudMask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    const ndvi = img.normalizedDifference(['B8', 'B4']).rename('ndvi');
    const mndwi = img.normalizedDifference(['B3', 'B11']);
    const waterMask = mndwi.lt(0.0); // keep non-water

    return ndvi.updateMask(cloudMask).updateMask(waterMask);
  });
}

// Landsat 8/9 SR scaling, cloud/water mask and NDVI
function prepLandsatToNdvi(col) {
  return col.map(function(img) {
    const scale = ee.Image(0.0000275);
    const offset = ee.Image(-0.2);
    const optical = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6']).multiply(scale).add(offset)
      .rename(['B2','B3','B4','B5','B6']);

    const qa = img.select('QA_PIXEL');
    const dilatedCloud = qa.bitwiseAnd(1 << 1).eq(0);
    const cirrus = qa.bitwiseAnd(1 << 2).eq(0);
    const cloud = qa.bitwiseAnd(1 << 3).eq(0);
    const cloudShadow = qa.bitwiseAnd(1 << 4).eq(0);
    const snow = qa.bitwiseAnd(1 << 5).eq(0);
    const cloudMask = dilatedCloud.and(cirrus).and(cloud).and(cloudShadow).and(snow);

    const ndvi = optical.normalizedDifference(['B5','B4']).rename('ndvi');
    const mndwi = optical.normalizedDifference(['B3','B6']);
    const waterMask = mndwi.lt(0.0);

    return ndvi.updateMask(cloudMask).updateMask(waterMask);
  });
}

async function buildNdviComposite(dateStr, geom) {
  const target = ee.Date(dateStr);
  const attempts = [
    {type: 'S2', window: 30},
    {type: 'LANDSAT', window: 45},
    {type: 'S2', window: 90},
    {type: 'LANDSAT', window: 120},
  ];

  for (let att of attempts) {
    const start = target.advance(-att.window, 'day');
    const end = target.advance(att.window + 1, 'day');
    if (att.type === 'S2') {
      let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(geom)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 90));
      const size = await getInfoAsync(col.size());
      if (size > 0) {
        const ndviCol = prepS2ToNdvi(col);
        const mosaic = ndviCol.median().clip(geom);
        return {img: mosaic, count: size, source: 'S2', windowDays: att.window};
      }
    } else {
      let l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(geom).filterDate(start, end);
      let l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(geom).filterDate(start, end);
      let col = l8.merge(l9);
      const size = await getInfoAsync(col.size());
      if (size > 0) {
        const ndviCol = prepLandsatToNdvi(col);
        const mosaic = ndviCol.median().clip(geom);
        return {img: mosaic, count: size, source: 'L8/L9', windowDays: att.window};
      }
    }
  }
  return {error: 'C1'};
}

async function computeStats(ndviImg, geom, forestThresh) {
  const scale = 1000; // per requirement
  const validCount = await getInfoAsync(
    ndviImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get('ndvi')
  );

  const totalCount = await getInfoAsync(
    ee.Image(1).rename('one').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get('one')
  );

  const cloudPct = (totalCount && validCount != null) ? Math.max(0, 100 * (1 - (validCount / totalCount))) : null;

  const forestMask = ndviImg.gte(forestThresh);
  const forestAreaM2 = await getInfoAsync(
    forestMask.selfMask().multiply(ee.Image.pixelArea()).rename('area').reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get('area')
  );
  const forestAreaKm2 = (forestAreaM2 != null) ? (forestAreaM2 / 1e6) : null;

  return {validCount, totalCount, cloudPct, forestAreaKm2};
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const center = {lat: -9.799994, lon: -73.845369};
    const geom = bufferCircle(center.lon, center.lat, 5000);
    const date2017 = '2017-08-23';
    const date2022 = '2022-08-21';
    const forestThresh = 0.6;

    // 2. Data Acquisition & Check with fallback
    const comp2017 = await buildNdviComposite(date2017, geom);
    if (comp2017.error === 'C1') {
      console.log(`2017 Images: 0`);
      console.log('C1');
      return;
    }
    const comp2022 = await buildNdviComposite(date2022, geom);
    if (comp2022.error === 'C1') {
      console.log(`2017 Images: ${comp2017.count} [${comp2017.source}, ±${comp2017.windowDays}d]`);
      console.log(`2022 Images: 0`);
      console.log('C1');
      return;
    }

    console.log(`2017 Images: ${comp2017.count} [${comp2017.source}, ±${comp2017.windowDays}d]`);
    console.log(`2022 Images: ${comp2022.count} [${comp2022.source}, ±${comp2022.windowDays}d]`);

    // 3. Processing & Pixel Count (detect C2)
    const stats2017 = await computeStats(comp2017.img, geom, forestThresh);
    const stats2022 = await computeStats(comp2022.img, geom, forestThresh);

    if ((stats2017.validCount || 0) === 0 || (stats2022.validCount || 0) === 0) {
      console.log(`2017 Valid px: ${stats2017.validCount || 0}, Cloud%: ${stats2017.cloudPct != null ? stats2017.cloudPct.toFixed(1) : 'NA'}`);
      console.log(`2022 Valid px: ${stats2022.validCount || 0}, Cloud%: ${stats2022.cloudPct != null ? stats2022.cloudPct.toFixed(1) : 'NA'}`);
      console.log('C2');
      return;
    }

    // 4. Calculation & Validation (detect C3)
    const a2017 = stats2017.forestAreaKm2;
    const a2022 = stats2022.forestAreaKm2;
    const invalid = (v) => (v === null || v === undefined || isNaN(v) || !isFinite(v) || v < 0 || v > 1000);
    if (invalid(a2017) || invalid(a2022)) {
      console.log(`2017 Forest km2: ${a2017 != null ? a2017.toFixed(2) : 'NA'}`);
      console.log(`2022 Forest km2: ${a2022 != null ? a2022.toFixed(2) : 'NA'}`);
      console.log('C3');
      return;
    }

    // 5. Print concise evidence and final answer
    console.log(`2017 Valid px: ${stats2017.validCount}, Cloud%: ${stats2017.cloudPct.toFixed(1)}`);
    console.log(`2022 Valid px: ${stats2022.validCount}, Cloud%: ${stats2022.cloudPct.toFixed(1)}`);
    console.log(`2017 Forest km2: ${a2017.toFixed(2)}`);
    console.log(`2022 Forest km2: ${a2022.toFixed(2)}`);

    if (a2022 > a2017) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error('Error:', err && err.message ? err.message : err);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
